#!/usr/bin/env python3

import os
import sys
import nltk
import json
from transformers import (
    AutoModel,
    AutoTokenizer,
    AutoConfig,
)
from sentence_transformers import SentenceTransformer
from optimum.onnxruntime import ORTModelForFeatureExtraction
from optimum.onnxruntime.configuration import AutoQuantizationConfig
from optimum.onnxruntime import ORTQuantizer
from pathlib import Path


model_dir = "./models/model"
nltk_dir = "./nltk_data"
model_name = os.getenv("MODEL_NAME", None)
force_automodel = os.getenv("FORCE_AUTOMODEL", False)
trust_remote_code = os.getenv("TRUST_REMOTE_CODE", False)
use_query_passage_prefixes = os.getenv("USE_QUERY_PASSAGE_PREFIXES", False)
use_query_prompt = os.getenv("USE_QUERY_PROMPT", False)
if not model_name:
    print("Fatal: MODEL_NAME is required")
    print(
        "Please set environment variable MODEL_NAME to a HuggingFace model name, see https://huggingface.co/models"
    )
    sys.exit(1)

if force_automodel:
    print(f"Using AutoModel for {model_name} to instantiate model")

onnx_runtime = os.getenv("ONNX_RUNTIME")
if not onnx_runtime:
    onnx_runtime = "false"

onnx_cpu_arch = os.getenv("ONNX_CPU")
if not onnx_cpu_arch:
    onnx_cpu_arch = "arm64"

use_sentence_transformers_vectorizer = os.getenv("USE_SENTENCE_TRANSFORMERS_VECTORIZER")
if not use_sentence_transformers_vectorizer:
    use_sentence_transformers_vectorizer = "false"

print(
    f"Downloading MODEL_NAME={model_name} with FORCE_AUTOMODEL={force_automodel} ONNX_RUNTIME={onnx_runtime} ONNX_CPU={onnx_cpu_arch}"
)


def download_onnx_model(
    model_name: str, model_dir: str, trust_remote_code: bool = False
):
    # Download model and tokenizer
    onnx_path = Path(model_dir)
    ort_model = ORTModelForFeatureExtraction.from_pretrained(
        model_name, trust_remote_code=trust_remote_code
    )
    # Save model
    ort_model.save_pretrained(onnx_path)

    def save_to_file(filepath: str, content: str):
        with open(filepath, "w") as f:
            f.write(content)

    def save_quantization_info(arch: str):
        save_to_file(f"{model_dir}/onnx_quantization_info", arch)

    def quantization_config(onnx_cpu_arch: str):
        if onnx_cpu_arch.lower() == "avx512_vnni":
            print("Quantize Model for x86_64 (amd64) (avx512_vnni)")
            save_quantization_info("AVX-512")
            return AutoQuantizationConfig.avx512_vnni(
                is_static=False, per_channel=False
            )
        if onnx_cpu_arch.lower() == "arm64":
            print(f"Quantize Model for ARM64")
            save_quantization_info("ARM64")
            return AutoQuantizationConfig.arm64(is_static=False, per_channel=False)
        # default is AMD64 (AVX2)
        print(f"Quantize Model for x86_64 (amd64) (AVX2)")
        save_quantization_info("amd64 (AVX2)")
        return AutoQuantizationConfig.avx2(is_static=False, per_channel=False)

    # Quantize the model / convert to ONNX
    qconfig = quantization_config(onnx_cpu_arch)
    quantizer = ORTQuantizer.from_pretrained(ort_model)
    # Apply dynamic quantization on the model
    quantizer.quantize(save_dir=onnx_path, quantization_config=qconfig)
    # Remove model.onnx file, leave only model_quantized.onnx
    if os.path.isfile(f"{model_dir}/model.onnx"):
        os.remove(f"{model_dir}/model.onnx")
    # Save information about ONNX runtime
    save_to_file(f"{model_dir}/onnx_runtime", onnx_runtime)
    tokenizer = AutoTokenizer.from_pretrained(
        model_name, trust_remote_code=trust_remote_code
    )
    tokenizer.save_pretrained(onnx_path)


def download_model(model_name: str, model_dir: str, trust_remote_code: bool = False):
    def save_model_name(model_name: str):
        with open(f"{model_dir}/model_name", "w") as f:
            f.write(model_name)

    def save_trust_remote_code(trust_remote_code: bool):
        with open(f"{model_dir}/trust_remote_code", "w") as f:
            f.write(f"{trust_remote_code}")

    def save_use_query_passage_prefixes(use_query_passage_prefixes: bool):
        with open(f"{model_dir}/use_query_passage_prefixes", "w") as f:
            f.write(f"{use_query_passage_prefixes}")

    def save_use_query_prompt(use_query_prompt: bool):
        with open(f"{model_dir}/use_query_prompt", "w") as f:
            f.write(f"{use_query_prompt}")

    def save_model_config(model_config):
        with open(f"{model_dir}/model_config", "w") as f:
            f.write(json.dumps(model_config))

    print(
        f"Downloading model {model_name} from huggingface model hub ({trust_remote_code=})"
    )
    try:
        config = AutoConfig.from_pretrained(
            model_name, trust_remote_code=trust_remote_code
        )
        config_dict = config.to_dict()
        model_type = config.to_dict()["model_type"]
    except ValueError as e:
        # Check if this is the specific model2vec error
        if "model type `model2vec`" in str(e):
            config_dict = {"model_type": "model2vec"}
            model_type = "model2vec"
        else:
            raise e

    if (
        model_type is not None and (model_type == "t5" or model_type == "model2vec")
    ) or use_sentence_transformers_vectorizer.lower() == "true":
        SentenceTransformer(
            model_name, cache_folder=model_dir, trust_remote_code=trust_remote_code
        )
        save_model_name(model_name)
        save_model_config(config_dict)
    else:
        if config.architectures and not force_automodel:
            print(f"Using class {config.architectures[0]} to load model weights")
            mod = __import__("transformers", fromlist=[config.architectures[0]])
            try:
                klass_architecture = getattr(mod, config.architectures[0])
                model = klass_architecture.from_pretrained(model_name)
            except AttributeError:
                print(
                    f"{config.architectures[0]} not found in transformers, fallback to AutoModel"
                )
                model = AutoModel.from_pretrained(
                    model_name, trust_remote_code=trust_remote_code
                )
        else:
            model = AutoModel.from_pretrained(
                model_name, trust_remote_code=trust_remote_code
            )

        tokenizer = AutoTokenizer.from_pretrained(
            model_name, trust_remote_code=trust_remote_code
        )

        model.save_pretrained(model_dir)
        tokenizer.save_pretrained(model_dir)

    save_trust_remote_code(trust_remote_code)
    save_use_query_passage_prefixes(use_query_passage_prefixes)
    save_use_query_prompt(use_query_prompt)

    nltk.download("punkt", download_dir=nltk_dir)
    nltk.download("punkt_tab", download_dir=nltk_dir)


if onnx_runtime == "true":
    download_onnx_model(model_name, model_dir, trust_remote_code)
else:
    download_model(model_name, model_dir, trust_remote_code)

import os
from typing import Optional, List
from logging import getLogger
from fastapi import FastAPI, Depends, Response, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from typing import Union
from config import (
    TRUST_REMOTE_CODE,
    USE_QUERY_PASSAGE_PREFIXES,
    USE_QUERY_PROMPT,
    get_allowed_tokens,
    get_use_sentence_transformers_multi_process,
    get_t2v_transformers_direct_tokenize,
)
from vectorizer import Vectorizer, VectorInput
from meta import Meta
import torch


logger = getLogger("uvicorn")

vec: Vectorizer
meta_config: Meta

get_bearer_token = [REDACTED]
allowed_tokens: List[str] = None
current_worker = 0
available_workers = 1


def is_authorized(auth: Optional[HTTPAuthorizationCredentials]) -> bool:
    if allowed_tokens is not None and (
        auth is None or auth.credentials not in allowed_tokens
    ):
        return False
    return True


def get_worker():
    if available_workers == 1:
        return 0
    else:
        global current_worker
        if current_worker >= 1_000_000_000:
            current_worker = 0
        worker = current_worker % available_workers
        current_worker += 1
        return worker


async def lifespan(app: FastAPI):
    global vec
    global meta_config
    global allowed_tokens
    global available_workers

    allowed_tokens = get_allowed_tokens()

    model_dir = "./models/model"

    def get_model_name() -> Union[str, bool]:
        if os.path.exists(f"{model_dir}/model_name"):
            with open(f"{model_dir}/model_name", "r") as f:
                model_name = f.read()
                return model_name, True
        # Default model directory is ./models/model
        return model_dir, False

    def get_onnx_runtime() -> bool:
        if os.path.exists(f"{model_dir}/onnx_runtime"):
            with open(f"{model_dir}/onnx_runtime", "r") as f:
                onnx_runtime = f.read()
                return onnx_runtime == "true"
        return False

    def get_trust_remote_code() -> bool:
        if os.path.exists(f"{model_dir}/trust_remote_code"):
            with open(f"{model_dir}/trust_remote_code", "r") as f:
                trust_remote_code = f.read()
                return trust_remote_code == "true"
        return TRUST_REMOTE_CODE

    def get_use_query_passage_prefixes() -> bool:
        if os.path.exists(f"{model_dir}/use_query_passage_prefixes"):
            with open(f"{model_dir}/use_query_passage_prefixes", "r") as f:
                use_query_passage_prefixes = f.read()
                return use_query_passage_prefixes == "true"
        return USE_QUERY_PASSAGE_PREFIXES

    def get_use_query_prompt() -> bool:
        if os.path.exists(f"{model_dir}/use_query_prompt"):
            with open(f"{model_dir}/use_query_prompt", "r") as f:
                use_query_prompt = f.read()
                return use_query_prompt == "true"
        return USE_QUERY_PROMPT

    def log_info_about_onnx(onnx_runtime: bool):
        if onnx_runtime:
            onnx_quantization_info = "missing"
            if os.path.exists(f"{model_dir}/onnx_quantization_info"):
                with open(f"{model_dir}/onnx_quantization_info", "r") as f:
                    onnx_quantization_info = f.read()
            logger.info(
                f"Running ONNX vectorizer with quantized model for {onnx_quantization_info}"
            )

    model_name, use_sentence_transformers_vectorizer = get_model_name()
    onnx_runtime = get_onnx_runtime()
    trust_remote_code = get_trust_remote_code()
    use_query_passage_prefixes = get_use_query_passage_prefixes()
    use_query_prompt = get_use_query_prompt()

    cuda_env = os.getenv("ENABLE_CUDA")
    cuda_per_process_memory_fraction = 1.0
    if "CUDA_PER_PROCESS_MEMORY_FRACTION" in os.environ:
        try:
            cuda_per_process_memory_fraction = float(
                os.getenv("CUDA_PER_PROCESS_MEMORY_FRACTION")
            )
        except ValueError:
            logger.error(
                f"Invalid CUDA_PER_PROCESS_MEMORY_FRACTION (should be between 0.0-1.0)"
            )
    if 0.0 <= cuda_per_process_memory_fraction <= 1.0:
        logger.info(
            f"CUDA_PER_PROCESS_MEMORY_FRACTION set to {cuda_per_process_memory_fraction}"
        )
    cuda_support = False
    cuda_core = ""
    # Use all sentence transformers multi process
    use_sentence_transformers_multi_process = (
        get_use_sentence_transformers_multi_process()
    )

    if cuda_env is not None and cuda_env == "true" or cuda_env == "1":
        cuda_support = True
        cuda_core = os.getenv("CUDA_CORE")
        if cuda_core is None or cuda_core == "":
            if (
                use_sentence_transformers_vectorizer
                and use_sentence_transformers_multi_process
                and torch.cuda.is_available()
            ):
                available_workers = torch.cuda.device_count()
                cuda_core = ",".join([f"cuda:{i}" for i in range(available_workers)])
            else:
                cuda_core = "cuda:0"
        logger.info(f"CUDA_CORE set to {cuda_core}")
    else:
        logger.info("Running on CPU")

    # Batch text tokenization enabled by default
    direct_tokenize = get_t2v_transformers_direct_tokenize()

    log_info_about_onnx(onnx_runtime)

    meta_config = Meta(
        model_dir,
        model_name,
        use_sentence_transformers_vectorizer,
        trust_remote_code,
    )

    if cuda_support is False and meta_config.get_model_type() == "model2vec":
        # in case of CPU we need to run this model explicitly on CPU device, not MPS device
        cuda_core = "cpu"

    vec = Vectorizer(
        model_dir,
        cuda_support,
        cuda_core,
        cuda_per_process_memory_fraction,
        meta_config.get_model_type(),
        meta_config.get_architecture(),
        direct_tokenize,
        onnx_runtime,
        use_sentence_transformers_vectorizer,
        use_sentence_transformers_multi_process,
        use_query_passage_prefixes,
        use_query_prompt,
        model_name,
        trust_remote_code,
        available_workers,
    )
    yield


